'use strict';
(() => {
const DATA=window.PREP_DATA, topics=DATA.topics, main=document.getElementById('main');
const all=topics.flatMap(t=>t.questions.map(q=>({...q,topic:t}))), byId=new Map(all.map(q=>[q.id,q]));
const KEY='genai-interview-studio-v2';
let storageOK=true, state={version:2,questions:{},last:null}, toastTimer, searchTimer;
try{const raw=localStorage.getItem(KEY);if(raw){const s=JSON.parse(raw);if(s.version===2&&s.questions&&typeof s.questions==='object')state=s;}}catch{storageOK=false;}
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr=escape;
const progress=id=>state.questions[id]||{};
const route=()=>{const raw=location.hash.slice(1)||'home';const at=raw.indexOf('?');return{path:(at<0?raw:raw.slice(0,at)).split('/'),params:new URLSearchParams(at<0?'':raw.slice(at+1))};};
const url=(t,mode,q)=>`#topic/${t.id}/${mode}${q?'?q='+encodeURIComponent(q.id):''}`;
function toast(msg){const e=document.getElementById('toast');e.textContent=msg;e.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.hidden=true,2500);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;toast('Browser storage is unavailable. Export your progress before closing.');}}
function update(id,patch){state.questions[id]={...progress(id),...patch};save();}
function stats(t){const qs=t?t.questions:all;return{total:qs.length,learned:qs.filter(q=>progress(q.id).learned).length,ready:qs.filter(q=>progress(q.id).rating==='ready').length,review:qs.filter(q=>progress(q.id).rating==='review').length};}
function pdf(t){return 'pdfs/'+encodeURIComponent(t.pdf);}
function heading(title,description,kicker='YOUR PREPARATION'){return `<div class="page-heading"><p class="eyebrow">${escape(kicker)}</p><h1>${escape(title)}</h1><p>${escape(description)}</p></div>`;}
function empty(title,msg,link='#home',label='Explore topics'){return `<div class="empty"><h2>${escape(title)}</h2><p>${escape(msg)}</p><a class="btn primary" href="${attr(link)}">${escape(label)}</a></div>`;}


const labels={Simple:'Definition / in plain language',Technical:'How it works',Example:'Worked example',Metrics:'How to evaluate it','Trade-offs':'Production trade-offs',Say:'Interview-ready answer',Note:'Study note'};


function toolbar(q){const s=progress(q.id);return `<div class="toolbar"><button class="btn small ${s.learned?'selected':''}" data-action="learned" data-id="${q.id}" aria-pressed="${!!s.learned}">${s.learned?'✓ Learned':'Mark learned'}</button><button class="btn small ${s.bookmarked?'selected':''}" data-action="bookmark" data-id="${q.id}" aria-pressed="${!!s.bookmarked}">${s.bookmarked?'★ Saved':'☆ Save question'}</button><button class="btn small ${s.rating==='review'?'selected':''}" data-action="review" data-id="${q.id}" aria-pressed="${s.rating==='review'}">${s.rating==='review'?'Needs review':'Review later'}</button></div>`;}
function notes(q){return `<div class="notes"><label for="note-${q.id}">Your notes & project evidence</label><textarea id="note-${q.id}" data-note="${q.id}" placeholder="Write your answer, a real example, or evidence you need to verify...">${escape(progress(q.id).note||'')}</textarea><div class="note-hint">Saved in this browser. Keep confidential client data out of your notes.</div></div>`;}
function sources(t){return `<details class="sources"><summary>Primary sources & further reading</summary>${t.sources.map(s=>`<a href="${attr(s.url)}" target="_blank" rel="noopener noreferrer">${escape(s.title)}</a>`).join('')}<p class="muted">Framework behavior changes by version. Verify your deployed configuration. Edition: ${DATA.edition}.</p></details>`;}
function topicHeader(t,mode){const s=stats(t);return `<div class="crumb"><a href="#${mode==='interview'?'interview':'learn'}">All topics</a> / ${escape(t.title)}</div><div class="topic-header"><div><p class="eyebrow">${escape(t.category)}</p><h1>${escape(t.title)}</h1><p class="description">${escape(t.description)}</p><div class="topic-meta">${t.questions.length} questions · ${t.questions.reduce((n,q)=>n+q.followups.length,0)} follow-ups · ${s.learned} learned</div></div><a class="btn" href="${pdf(t)}" target="_blank" rel="noopener" download>Download PDF</a></div><nav class="tabs" aria-label="Topic view"><a class="${mode==='learn'?'active':''}" href="${url(t,'learn')}">Learn</a><a class="${mode==='interview'?'active':''}" href="${url(t,'interview')}">Interview guide</a><a class="${mode==='practice'?'active':''}" href="${url(t,'practice')}">Practice</a></nav>${t.intro.length?`<details class="callout topic-overview"><summary>Topic overview & preparation notes</summary>${t.intro.map(b=>`<p><strong>${escape(b.label==='Architecture'?'Reference architecture':'Study note')}</strong>${escape(b.text)}</p>`).join('')}</details>`:''}`;}
function learnView(t,params){
 const weight=q=>/^What does retrieval-augmented|^What is generative AI|^What are variables|^What is an API,|^What is LlamaIndex\?|^What are state,|^What is fixed-size/.test(q.title)?-1:q.kind==='Foundation'?0:1; const lessons=[...t.questions].sort((a,b)=>weight(a)-weight(b));
 const q=lessons.find(q=>q.id===params.get('q'))||lessons[0];
 state.last=q.id;save();const at=lessons.indexOf(q);
 return topicHeader(t,'learn')+`<div class="reader"><aside class="lesson-nav" aria-label="Lessons"><h3>LEARNING PATH</h3>${lessons.map(x=>`<a href="${url(t,'learn',x)}" class="${x.id===q.id?'current':''}" ${x.id===q.id?'aria-current="page"':''}>${progress(x.id).learned?'<span class="done">✓</span>':''}${escape(x.title)}</a>`).join('')}</aside><article class="article"><span class="pill">${escape(q.kind)}</span><span class="muted"> · ${at+1} of ${lessons.length}</span><h2>${escape(q.title)}</h2>${toolbar(q)}${blocks(q,true)}${followups(q)}${notes(q)}<div class="reader-controls">${at>0?`<a class="btn" href="${url(t,'learn',lessons[at-1])}">Previous lesson</a>`:'<span></span>'}${at<lessons.length-1?`<a class="btn primary" href="${url(t,'learn',lessons[at+1])}">Next lesson</a>`:`<a class="btn primary" href="${url(t,'practice')}">Practice this topic</a>`}</div>${sources(t)}</article></div>`;
}
function questionCard(q,open=false){return `<article class="question-card" id="card-${q.id}"><button class="question-trigger" data-action="expand" data-id="${q.id}" aria-expanded="${open}" aria-controls="body-${q.id}"><span><span class="pill ${q.kind==='Scenario'?'scenario':''}">${escape(q.kind)}</span>${progress(q.id).rating==='review'?' <span class="review-label">Needs review</span>':''}<strong>${escape(q.title)}</strong><span class="muted">${escape(q.section)} · ${q.followups.length} follow-ups</span></span><span class="expand" aria-hidden="true">${open?'−':'+'}</span></button><div class="question-body" id="body-${q.id}" ${open?'':'hidden'}><div class="article">${toolbar(q)}${blocks(q)}${followups(q)}${notes(q)}<div class="reader-controls"><a class="btn small" href="${url(q.topic,'learn',q)}">Open as lesson</a><a class="btn small" href="${url(q.topic,'practice',q)}">Practice this question</a></div></div></div></article>`;}
function interviewView(t,params){const kind=params.get('kind')||'All',section=params.get('section')||'All';const qs=t.questions.filter(q=>(kind==='All'||q.kind===kind)&&(section==='All'||q.section===section));return topicHeader(t,'interview')+`<div class="callout"><strong>Answer first. Then compare.</strong>Explain the main idea aloud, sketch the flow and choose a trade-off before opening the answer. Each follow-up has its own answer to reveal.</div><div class="filters"><label for="kind-filter">Question type</label><select id="kind-filter" data-filter="kind">${['All','Foundation','Deep dive','Scenario'].map(k=>`<option ${k===kind?'selected':''}>${k}</option>`).join('')}</select><label for="section-filter">Section</label><select id="section-filter" data-filter="section">${['All',...new Set(t.questions.map(q=>q.section))].map(s=>`<option value="${attr(s)}" ${s===section?'selected':''}>${escape(s)}</option>`).join('')}</select></div><p class="countline">${qs.length} questions shown</p><div class="question-list">${qs.length?qs.map(q=>questionCard({...q,topic:t},q.id===params.get('q'))).join(''):empty('No questions in this filter','Try another section or question type.',url(t,'interview'),'Clear filters')}</div>${sources(t)}`;}


function result(q){const def=q.blocks.find(b=>b.label==='Simple')?.text||'';return `<a class="result" href="${url(q.topic,'interview',q)}"><small>${escape(q.topic.title)} · ${escape(q.kind)} · ${q.followups.length} follow-ups</small><h3>${escape(q.title)}</h3><p>${escape(def)}</p></a>`;}
function searchView(params){const term=(params.get('q')||'').trim(),words=term.toLowerCase().split(/\s+/).filter(Boolean);const results=words.length?all.filter(q=>words.every(w=>q.search.includes(w)||q.topic.title.toLowerCase().includes(w))).sort((a,b)=>Number(b.title.toLowerCase().includes(term.toLowerCase()))-Number(a.title.toLowerCase().includes(term.toLowerCase()))):[];return heading('Find the concept. Follow the question.',`Search across definitions, technical explanations, examples and every follow-up answer.`,'SEARCH')+`<p class="countline">${results.length} results${term?' for “'+escape(term)+'”':''}</p>`+(results.length?`<div class="results">${results.map(result).join('')}</div>`:empty(term?'No matching questions':'Start with a concept',term?'Try a shorter term such as RRF, query rewriting, LangSmith, GPU or authentication.':'Use the search field above to find a topic or a difficult follow-up.','#learn','Browse topics'));}
function savedView(params){const filter=params.get('filter')||'saved',qs=all.filter(q=>filter==='review'?progress(q.id).rating==='review':progress(q.id).bookmarked);return heading('Keep your next revision focused.','Save important questions and mark difficult concepts for another pass.','SAVED & REVIEW')+`<div class="chips"><a class="chip ${filter==='saved'?'active':''}" href="#saved?filter=saved">Saved questions</a><a class="chip ${filter==='review'?'active':''}" href="#saved?filter=review">Needs review</a></div>`+(qs.length?`<p class="countline">${qs.length} questions</p><div class="results">${qs.map(result).join('')}</div>`:empty(filter==='review'?'Your review list is clear':'Save your first question',filter==='review'?'Mark a question “Review later” or grade a practice answer as needing more practice.':'Use “Save question” inside any lesson or interview answer.','#interview','Explore the question bank'));}
function progressView(){const s=stats();return heading('See what is sticking.','Your marks and notes are stored in this browser. Export them to back up your preparation or move to another device.','MY PROGRESS')+`<div class="stats"><div class="stat"><strong>${s.learned}/${s.total}</strong><span>Marked learned</span></div><div class="stat"><strong>${s.ready}</strong><span>Self-rated ready</span></div><div class="stat"><strong>${s.review}</strong><span>Need another pass</span></div><div class="stat"><strong>${all.filter(q=>progress(q.id).note?.trim()).length}</strong><span>Questions with notes</span></div></div><div class="actions"><button class="btn primary" data-action="export">Export progress</button><button class="btn" data-action="import">Import backup</button><input type="file" id="import-file" accept="application/json,.json" hidden><button class="btn ghost" data-action="reset">Reset progress</button></div><div class="callout">Progress is a self-assessment. “Learned” and “ready” do not automatically mean an answer is correct. Rehearse without notes and verify project-specific evidence.</div><div class="section-row"><h2>Progress by topic</h2><a href="#saved?filter=review">Review difficult questions</a></div>${topics.map(t=>{const x=stats(t);return `<div class="progress-row"><div><h3>${escape(t.title)}</h3><small>${x.ready} ready · ${x.review} to review</small></div><div><small>${x.learned} of ${x.total} learned</small><div class="bar"><span style="width:${x.learned/x.total*100}%"></span></div></div><a class="btn small" href="${url(t,'learn')}">Continue</a></div>`}).join('')}`;}
function closeMenu(){document.getElementById('sidebar').classList.remove('open');document.getElementById('overlay').hidden=true;document.getElementById('menu').setAttribute('aria-expanded','false');}
function render(preserve=false){const y=scrollY,{path,params}=route();closeMenu();let out='';if(path[0]==='topic'){const t=topics.find(t=>t.id===path[1]);out=t?(path[2]==='interview'?interviewView(t,params):path[2]==='practice'?practiceView(t,params):learnView(t,params)):empty('Topic not found','Choose a topic from the library.','#learn','Browse topics');}else if(['home','learn','interview'].includes(path[0]))out=catalog(path[0],params.get('category')||'All');else if(path[0]==='search')out=searchView(params);else if(path[0]==='scenarios')out=scenariosView(params);else if(path[0]==='saved')out=savedView(params);else if(path[0]==='progress')out=progressView();else out=empty('Page not found','Return to your study library.');
 main.innerHTML=(!storageOK?'<div class="warning">Browser storage is unavailable. Export progress before closing; automatic saving may not persist.</div>':'')+out;
 mountExperience();
 const active=path[0]==='topic'?(path[2]==='learn'?'learn':'interview'):path[0];document.querySelectorAll('[data-nav]').forEach(a=>{const yes=a.dataset.nav===active;a.classList.toggle('active',yes);if(yes)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 if(path[0]==='search'&&document.activeElement.id!=='search')document.getElementById('search').value=params.get('q')||'';
 document.title=(path[0]==='topic'?(topics.find(t=>t.id===path[1])?.title||'Topic'):'Your study desk')+' | PrepAtoZ';
 if(preserve)scrollTo(0,y);else if(path[0]==='topic'&&path[2]==='interview'&&params.get('q'))requestAnimationFrame(()=>document.getElementById('card-'+params.get('q'))?.scrollIntoView({block:'start'}));else scrollTo(0,0);
}
/* PrepAtoZ experience: preserved question IDs and progress storage. */
let clockInterval, clockEnds=0, clockRemaining=120;
const topicTone=id=>({rag:'green',agents:'orange',llms:'blue',ml:'orange',aws:'blue',gpu:'purple',python:'green'}[id]||'neutral');
const LABS={
 retrieval:{label:'Wrong context',tag:'RAG INCIDENT',title:'The answer sounds right. The source is from 2024.',symptom:'A user asks for the current refund policy. Your retriever sends last year’s policy to the LLM. The model quotes it confidently.',choices:['Add more few-shot examples','Inspect source versions and effective-date filters','Increase temperature'],correct:1,why:'Start at the evidence boundary. Verify source applicability and the actual retrieved chunk IDs before changing the model. More examples cannot make an obsolete policy current.',topic:'rag',match:'RAG passes the wrong context'},
 generation:{label:'Wrong answer',tag:'LLM INCIDENT',title:'The exception is in the context. The answer ignores it.',symptom:'The exact policy is retrieved, but the generated answer drops a critical exception. What do you inspect first?',choices:['The tokenized prompt, truncation and claim support','Re-embed the entire corpus immediately','Add more API replicas'],correct:0,why:'Confirm the required span survived assembly, then test interpretation and source support. Retrieval, generation and serving capacity are different failure stages.',topic:'rag',match:'right context is present'},
 agents:{label:'Stuck agents',tag:'WORKFLOW INCIDENT',title:'The planner finished. The workflow never comes back.',symptom:'A tool request timed out halfway through a multi-agent run. You do not know whether the remote report was created.',choices:['Restart all agents with a new request ID','Retry forever until the tool responds','Inspect the checkpoint and reconcile the operation ID'],correct:2,why:'A timeout is an unknown outcome, not proof that nothing happened. Reconcile the external operation, then resume compatible state with bounded retries and idempotency.',topic:'agents',match:'workflow gets stuck'},
 scaling:{label:'Traffic spike',tag:'AWS INCIDENT',title:'Ten times the traffic. The model quota stays the same.',symptom:'Your API can scale out, but inference calls are throttled and the database pool is filling. What is the best next move?',choices:['Add unbounded API replicas','Apply admission budgets and scale the actual bottleneck','Retry every throttled request immediately'],correct:1,why:'Scale API, database and model capacity as separate budgets. More replicas can amplify a constrained dependency. Use fair quotas, bounded queues and explicit overload behavior.',topic:'aws',match:'ten times the traffic'}
};
function dailyQuestion(){const day=new Date().toLocaleDateString('en-CA');let n=0;for(const c of day)n=(n*31+c.charCodeAt(0))>>>0;const candidates=all.filter(q=>q.kind==='Scenario');return candidates[n%candidates.length];}
function topicCard(t,mode='learn'){
 const s=stats(t),f=t.questions.reduce((n,q)=>n+q.followups.length,0),index=topics.indexOf(t);
 const symbol={python:'{ }',llms:'L',rag:'R',agents:'A',ml:'ML',aws:'aws',gpu:'GPU',sql:'SQL',resume:'CV',start:'▶'}[t.id]||t.title.slice(0,2);
 return `<article class="course tone-${topicTone(t.id)}"><div class="course-head"><span class="topic-symbol">${escape(symbol)}</span><span class="track-number">TRACK ${String(index+1).padStart(2,'0')}</span></div><h3><a href="${url(t,mode)}">${escape(t.title)}</a></h3><p>${escape(t.description)}</p><div class="course-meta"><span>${s.total} questions</span><span>${f} follow-ups</span></div><div class="bar" role="progressbar" aria-label="${attr(t.title)} progress" aria-valuenow="${s.learned}" aria-valuemin="0" aria-valuemax="${s.total}"><span style="width:${s.learned/s.total*100}%"></span></div><div class="actions"><a class="btn small" href="${url(t,'learn')}">Start learning</a><a class="textlink" href="${url(t,'interview')}">Interview guide</a></div></article>`;
}
function diagnostic(key='retrieval'){
 const x=LABS[key];return `<div class="lab-heading"><span class="eyebrow">${x.tag}</span><span class="lab-live">Interactive drill</span></div><h3>${x.title}</h3><p>${x.symptom}</p><div class="lab-choices" role="group" aria-label="Choose your first debugging step">${x.choices.map((v,i)=>`<button data-action="lab-answer" data-lab="${key}" data-choice="${i}"><span>${String.fromCharCode(65+i)}</span>${v}</button>`).join('')}</div><div id="lab-feedback" role="status" aria-live="polite" hidden></div>`;
}
function catalog(mode='home',category='All'){
 const s=stats(),f=all.reduce((n,q)=>n+q.followups.length,0),scenarioCount=all.filter(q=>q.kind==='Scenario').length,daily=dailyQuestion(),last=byId.get(state.last)||daily;
 let out='';
 if(mode==='home'){
 out=`<div class="desk-heading"><div><p class="eyebrow">YOUR PERSONAL STUDY DESK</p><h1>Make your next answer<br><em>the one that clicks.</em></h1></div><span class="desk-date">${escape(new Date().toLocaleDateString('en-IN',{weekday:'short',day:'numeric',month:'long'}))}</span></div><div class="desk-top"><section class="desk-hero"><div class="hero-line"><span>LEARN THE WHY. PRACTICE THE HOW.</span><svg viewBox="0 0 160 55" aria-hidden="true"><path d="M0 28h32l10-18 18 36 16-30 12 12h72"/></svg></div><h2>Less memorising.<br>More <span>“here’s how I’d build it.”</span></h2><p>From first principles to production incidents. Pick a track, try an answer, then handle the follow-up.</p><div class="actions"><a class="btn primary" href="${url(last.topic,'learn',last)}">${state.last?'Resume learning':'Start a scenario'}</a><a class="hero-text-link" href="#topic/resume/interview">Rehearse my projects</a></div><div class="hero-bottom"><span>${topics.length} study tracks</span><span>${all.length} questions</span><span>${scenarioCount} architecture drills</span></div></section><aside class="daily-card"><span class="eyebrow">TODAY'S TWO-MINUTE REP</span><div class="daily-symbol" aria-hidden="true">02<span>MIN</span></div><h3>${escape(daily.title.replace(/^Scenario: /,''))}</h3><p>Think aloud. Commit to a design. Then open the answer.</p><a class="btn" href="${url(daily.topic,'practice',daily)}">Try this question</a><small>Changes daily · no score pressure</small></aside></div><section class="diagnostic-desk"><div class="section-row"><div><p class="eyebrow">ON CALL, IN THE INTERVIEW</p><h2>Something broke. Where do you start?</h2></div><span class="muted">Choose a failure, then a fix.</span></div><div class="diagnostic-tabs" role="group" aria-label="Choose an incident">${Object.entries(LABS).map(([k,x])=>`<button class="${k==='retrieval'?'active':''}" data-action="lab" data-lab="${k}" aria-pressed="${k==='retrieval'}">${x.label}</button>`).join('')}</div><div id="diagnostic-panel" class="diagnostic-panel">${diagnostic()}</div></section>`;
 if(s.learned||s.review)out+=`<div class="study-pulse"><div><span class="pulse-ring" style="--p:${Math.round(s.learned/s.total*100)}%">${s.learned}</span><div><strong>Your preparation is taking shape.</strong><span>${s.learned} learned · ${s.review} to revisit · ${s.ready} self-rated ready</span></div></div><a href="#progress">View my progress</a></div>`;
 }else out=heading(mode==='learn'?'Find your next “aha”.':'A better answer starts here.',mode==='learn'?'Build understanding in order: the idea, the mechanism, a worked example, then the tough follow-up.':'Choose a topic, try the question out loud and compare your reasoning with the detailed answer.','THE PREPATOZ LIBRARY');
 out+=`<div class="section-row track-heading"><div><p class="eyebrow">${mode==='home'?'PICK YOUR NEXT CHAPTER':'A PLACE FOR EVERY CONCEPT'}</p><h2>${mode==='interview'?'Question bank, by topic':'Your study tracks'}</h2></div><span class="library-count">${all.length} questions <span> / </span> ${f} follow-ups</span></div><div class="chips">${['All','Foundations','Retrieval','Build','Operations','Practice'].map(c=>`<button class="chip ${c===category?'active':''}" data-action="category" data-value="${c}" aria-pressed="${c===category}">${c}</button>`).join('')}</div><div class="grid">${topics.filter(t=>category==='All'||t.category===category).map(t=>topicCard(t,mode==='interview'?'interview':'learn')).join('')}</div>`;return out;
}
function blocks(q,learn=false){
 const available=['All','Concept','Technical','Example','Architecture'].filter(x=>x==='All'||q.blocks.some(b=>({Simple:'Concept',Technical:'Technical',Example:'Example',Code:'Example',Architecture:'Architecture',Metrics:'Architecture','Trade-offs':'Architecture',Say:'Architecture'})[b.label]===x));
 return `<div class="answer-workbench" data-workbench><div class="answer-tabs" role="group" aria-label="Explore the answer">${available.map((v,i)=>`<button class="${i===0?'active':''}" data-action="answer-panel" data-panel="${v}" aria-pressed="${i===0}">${v==='All'?'Full answer':v}</button>`).join('')}</div><div class="answer-blocks">${q.blocks.map((b,i)=>{
 const group=({Simple:'Concept',Technical:'Technical',Example:'Example',Code:'Example',Architecture:'Architecture',Metrics:'Architecture','Trade-offs':'Architecture',Say:'Architecture'})[b.label]||'Technical';
 if(b.label==='Code')return `<section class="block" data-answer-group="${group}"><span class="block-label">TRY IT IN CODE</span><div class="code-wrap"><button class="copy" data-action="copy" data-id="${q.id}" data-index="${i}">Copy code</button><pre><code>${escape(b.text)}</code></pre></div></section>`;
 if(b.label==='Architecture')return `<section class="block architecture-block" data-answer-group="${group}"><span class="block-label">THE SYSTEM, STEP BY STEP</span><ol class="flow">${b.text.split(' -> ').map((x,j)=>`<li><b>${String(j+1).padStart(2,'0')}</b>${escape(x)}</li>`).join('')}</ol></section>`;
 const cls=b.label==='Simple'?'definition':b.label==='Example'?'example':b.label==='Say'?'spoken':b.label==='Metrics'?'metrics-block':b.label==='Trade-offs'?'tradeoff-block':'';
 const label=({Simple:'THE IDEA, SIMPLY',Technical:'UNDER THE HOOD',Example:'MAKE IT CONCRETE',Metrics:'WHAT GOOD LOOKS LIKE','Trade-offs':'THE TRADE-OFF',Say:'SAY IT IN THE INTERVIEW',Note:'KEEP IN MIND'})[b.label]||b.label;
 return `<section class="block ${cls}" data-answer-group="${group}"><h3 class="block-label">${escape(label)}</h3><p>${escape(b.text)}</p></section>`;
 }).join('')}</div></div>`;
}
function followups(q){return q.followups.length?`<section class="followups"><div class="section-row"><div><p class="eyebrow">THE INTERVIEWER PUSHES BACK</p><h3>Ready for the follow-up?</h3></div><span class="follow-count">${q.followups.length} challenges</span></div><p class="follow-intro">Try a sentence in your own words before revealing each answer.</p>${q.followups.map((f,i)=>`<details class="follow"><summary><span class="follow-index">${String(i+1).padStart(2,'0')}</span><span>${escape(f.question)}<small>Think first. Click to compare your reasoning.</small></span><span class="follow-toggle" aria-hidden="true">+</span></summary><div class="follow-answer"><span class="block-label">A STRONG ANSWER</span><p>${escape(f.answer)}</p><button class="textlink" data-action="follow-check">I can explain this</button></div></details>`).join('')}</section>`:'';}
function practiceView(t,params){
 const q=t.questions.find(q=>q.id===params.get('q'))||t.questions[0],at=t.questions.indexOf(q),revealed=params.get('answer')==='1';
 return topicHeader(t,'practice')+`<div class="practice"><section class="practice-card"><div class="section-row"><span class="eyebrow">YOUR TURN · ${at+1} / ${t.questions.length}</span><button class="btn small" data-action="random" data-topic="${t.id}">Shuffle question</button></div><h2>${escape(q.title)}</h2><div class="talk-structure"><span>Define the problem</span><span>Sketch the flow</span><span>Defend a trade-off</span><span>Name a metric</span></div><div class="practice-clock"><div><span class="clock-digits" id="practice-clock" aria-live="off">02:00</span><span class="clock-label" id="clock-label">Your two-minute thinking space</span></div><div class="actions"><button class="btn small" data-action="clock">Start timer</button><button class="textlink" data-action="clock-reset">Reset</button></div></div>${notes(q)}${!revealed?`<button class="btn primary reveal-main" data-action="reveal" data-id="${q.id}">Compare with a strong answer</button>`:`<div class="article">${blocks(q)}${followups(q)}</div><div class="grade"><h3>Could you defend it without notes?</h3><p>This is your self-assessment, not an AI-generated score.</p><div class="actions"><button class="btn" data-action="grade" data-id="${q.id}" data-value="review">Give it another pass</button><button class="btn primary" data-action="grade" data-id="${q.id}" data-value="ready">I can explain it</button></div></div>`}<div class="reader-controls">${at?`<a class="btn" href="${url(t,'practice',t.questions[at-1])}">Previous question</a>`:'<span></span>'}<a class="btn" href="${at<t.questions.length-1?url(t,'practice',t.questions[at+1]):'#progress'}">${at<t.questions.length-1?'Next question':'Review progress'}</a></div></section></div>`;
}
function scenariosView(params){const cat=params.get('group')||'All',selections=all.filter(q=>q.kind==='Scenario'&&(cat==='All'||q.topic.id===cat));return heading('Design it. Break it. Fix it.','Practice production decisions: inspect the evidence, choose the repair, defend the alternative. Every scenario includes architecture, metrics and difficult answered follow-ups.','THE SCENARIO WORKSHOP')+`<div class="chips">${[['All','All incidents'],['rag','RAG failures'],['llms','LLM decisions'],['agents','Multi-agent recovery'],['aws','AWS & scaling'],['ml','ML in production'],['systems','Development'],['domains','Domain scenarios'],['mock','Mock rounds']].map(([v,l])=>`<button class="chip ${cat===v?'active':''}" data-action="scenario-filter" data-value="${v}" aria-pressed="${cat===v}">${l}</button>`).join('')}</div><p class="countline">${selections.length} scenarios · answer first, then compare</p><div class="results">${selections.map(result).join('')}</div>`;}
function mountExperience(){
 clearInterval(clockInterval);clockEnds=0;clockRemaining=120;
 const article=main.querySelector('.reader>.article');if(article){const b=document.createElement('button');b.className='focus-switch';b.dataset.action='focus';b.textContent=document.body.classList.contains('focus-mode')?'Exit focus mode':'Focus mode';article.prepend(b);}
 if(!main.querySelector('.reader'))document.body.classList.remove('focus-mode');
}
function clockPaint(){const e=document.getElementById('practice-clock');if(!e)return;const n=clockEnds?Math.max(0,Math.ceil((clockEnds-Date.now())/1000)):clockRemaining;e.textContent=String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');if(!n){clearInterval(clockInterval);clockEnds=0;clockRemaining=0;document.getElementById('clock-label').textContent='Time. Wrap up your answer, then compare.';const b=main.querySelector('[data-action="clock"]');if(b)b.textContent='Finished';}}
try{document.documentElement.dataset.theme=localStorage.getItem('prepatoz-theme')||'light';}catch{}
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
 if(a==='theme'){const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';try{localStorage.setItem('prepatoz-theme',dark?'dark':'light');}catch{}b.setAttribute('aria-label',dark?'Switch to light theme':'Switch to dark theme');}
 else if(a==='focus'){document.body.classList.toggle('focus-mode');b.textContent=document.body.classList.contains('focus-mode')?'Exit focus mode':'Focus mode';}
 else if(a==='answer-panel'){const box=b.closest('[data-workbench]');box.querySelectorAll('.answer-tabs button').forEach(x=>{const on=x===b;x.classList.toggle('active',on);x.setAttribute('aria-pressed',on);});box.querySelectorAll('[data-answer-group]').forEach(x=>x.hidden=b.dataset.panel!=='All'&&x.dataset.answerGroup!==b.dataset.panel);}
 else if(a==='follow-check'){const done=b.classList.toggle('checked');b.textContent=done?'✓ Explained in my own words':'I can explain this';b.setAttribute('aria-pressed',done);}
 else if(a==='lab'){main.querySelectorAll('[data-action="lab"]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b);});document.getElementById('diagnostic-panel').innerHTML=diagnostic(b.dataset.lab);}
 else if(a==='lab-answer'){const x=LABS[b.dataset.lab],correct=Number(b.dataset.choice)===x.correct,panel=b.closest('.diagnostic-panel'),feedback=document.getElementById('lab-feedback');panel.querySelectorAll('[data-action="lab-answer"]').forEach(y=>{y.classList.toggle('chosen',y===b);y.classList.toggle('correct',Number(y.dataset.choice)===x.correct);y.classList.toggle('incorrect',y===b&&!correct);});const q=all.find(q=>q.topic.id===x.topic&&q.title.includes(x.match));feedback.hidden=false;feedback.className='lab-feedback '+(correct?'good':'rethink');feedback.innerHTML=`<strong>${correct?'That is the right first boundary.':'Pause here. Trace the failure before changing the system.'}</strong><p>${x.why}</p>${q?`<a class="textlink" href="${url(q.topic,'learn',q)}">Explore the complete architecture and follow-ups</a>`:''}`;}
 else if(a==='clock'){if(clockEnds){clockRemaining=Math.max(0,Math.ceil((clockEnds-Date.now())/1000));clockEnds=0;clearInterval(clockInterval);b.textContent='Resume timer';}else if(clockRemaining){clockEnds=Date.now()+clockRemaining*1000;clockInterval=setInterval(clockPaint,250);b.textContent='Pause timer';}clockPaint();}
 else if(a==='clock-reset'){clearInterval(clockInterval);clockEnds=0;clockRemaining=120;clockPaint();document.getElementById('clock-label').textContent='Your two-minute thinking space';main.querySelector('[data-action="clock"]').textContent='Start timer';}
});

document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id,q=byId.get(id),r=route();
 if(a==='category'){location.hash=r.path[0]+'?category='+encodeURIComponent(b.dataset.value);}
 else if(a==='scenario-filter'){location.hash='scenarios?group='+encodeURIComponent(b.dataset.value);}
 else if(a==='expand'){const body=document.getElementById('body-'+id),open=body.hidden;body.hidden=!open;b.setAttribute('aria-expanded',String(open));b.querySelector('.expand').textContent=open?'−':'+';}
 else if(['learned','bookmark','review'].includes(a)){const s=progress(id);update(id,a==='learned'?{learned:!s.learned}:a==='bookmark'?{bookmarked:!s.bookmarked}:{rating:s.rating==='review'?null:'review'});if(a==='learned'){b.textContent=progress(id).learned?'✓ Learned':'Mark learned';b.classList.toggle('selected',!!progress(id).learned);b.setAttribute('aria-pressed',String(!!progress(id).learned));}else if(a==='bookmark'){b.textContent=progress(id).bookmarked?'★ Saved':'☆ Save question';b.classList.toggle('selected',!!progress(id).bookmarked);b.setAttribute('aria-pressed',String(!!progress(id).bookmarked));}else{b.textContent=progress(id).rating==='review'?'Needs review':'Review later';b.classList.toggle('selected',progress(id).rating==='review');b.setAttribute('aria-pressed',String(progress(id).rating==='review'));}toast('Progress saved');}
 else if(a==='copy'){const text=q.blocks[Number(b.dataset.index)].text;try{await navigator.clipboard.writeText(text);toast('Code copied');}catch{const ta=document.createElement('textarea');ta.value=text;document.body.appendChild(ta);ta.select();const ok=document.execCommand('copy');ta.remove();toast(ok?'Code copied':'Select the code and copy it manually.');}}
 else if(a==='reveal'){location.hash=`topic/${q.topic.id}/practice?q=${id}&answer=1`;}
 else if(a==='random'){const t=topics.find(t=>t.id===b.dataset.topic);const choices=t.questions.filter(x=>x.id!==r.params.get('q'));const pick=choices[Math.floor(Math.random()*choices.length)]||t.questions[0];location.hash=url(t,'practice',pick);}
 else if(a==='grade'){update(id,{rating:b.dataset.value,...(b.dataset.value==='ready'?{learned:true}:{})});toast(b.dataset.value==='ready'?'Marked ready. Try the next question.':'Added to your review list.');b.closest('.grade').querySelectorAll('button').forEach(x=>x.classList.toggle('selected',x===b));}
 else if(a==='export'){const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});const u=URL.createObjectURL(blob),link=document.createElement('a');link.href=u;link.download='prepatoz-progress.json';link.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
 else if(a==='import')document.getElementById('import-file').click();
 else if(a==='reset'&&confirm('Reset all learning marks, saved questions and notes in this browser? Export a backup first if you want to keep them.')){state={version:2,questions:{},last:null};save();render();toast('Progress reset');}
});
document.addEventListener('input',e=>{if(e.target.dataset.note)update(e.target.dataset.note,{note:e.target.value.slice(0,20000)});});
document.addEventListener('change',async e=>{if(e.target.dataset.filter){const r=route();r.params.set(e.target.dataset.filter,e.target.value);r.params.delete('q');location.hash=r.path.join('/')+'?'+r.params.toString();}if(e.target.id==='import-file'){try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw Error('Backup is too large.');const parsed=JSON.parse(await file.text());if(parsed.version!==2||!parsed.questions||Array.isArray(parsed.questions)||typeof parsed.questions!=='object')throw Error('This is not a valid PrepAtoZ backup.');let n=0;for(const [id,v] of Object.entries(parsed.questions)){if(!byId.has(id)||!v||typeof v!=='object')continue;state.questions[id]={learned:v.learned===true,bookmarked:v.bookmarked===true,rating:['ready','review'].includes(v.rating)?v.rating:null,note:typeof v.note==='string'?v.note.slice(0,20000):''};n++;}save();render();toast(`Imported ${n} question records.`);}catch(err){toast(err.message||'Could not import this file.');}}});
const search=document.getElementById('search');document.getElementById('search-form').addEventListener('submit',e=>{e.preventDefault();clearTimeout(searchTimer);location.hash=search.value.trim()?'search?q='+encodeURIComponent(search.value.trim()):'learn';});search.addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if(search.value.trim())location.hash='search?q='+encodeURIComponent(search.value.trim());else if(route().path[0]==='search')location.hash='learn';},250);});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();search.focus();}if(e.key==='Escape'){closeMenu();search.blur();}});
document.getElementById('menu').addEventListener('click',()=>{const open=!document.getElementById('sidebar').classList.contains('open');document.getElementById('sidebar').classList.toggle('open',open);document.getElementById('overlay').hidden=!open;document.getElementById('menu').setAttribute('aria-expanded',String(open));});document.getElementById('overlay').addEventListener('click',closeMenu);
window.addEventListener('hashchange',()=>render());render();
})();
